 static void Check(bool value,string why){if(!value)throw new InvalidDataException("Chest surface: "+why);}
 public static void Validate(SmallPropsV1.Data all){var d=all.chestSurfacesV1;if(d==null||string.IsNullOrEmpty(d.id)&&d.version==0)return;Check(d.version==1&&d.id=="chest-surface-atlas-v1"&&d.size==512&&d.assets!=null&&d.assets.Length>0&&d.assets.Length<=7,"version/count");Check(d.colour!=null&&d.colour.colorSpace=="sRGB"&&d.packed!=null&&d.packed.colorSpace=="linear"&&d.packed.channels=="normalX-normalY-roughness-occlusion","map contract");foreach(var image in new[]{d.colour,d.packed})Check(!string.IsNullOrEmpty(image.png)&&image.png.Length<2000000,"image payload");Check(d.woodRect!=null&&d.woodRect.Length==4&&d.woodRect[0]>=0&&d.woodRect[1]>=0&&d.woodRect[1]<=1&&d.woodRect[2]<=1&&d.woodRect[3]>=0&&d.woodRect[3]<=1&&d.woodRect[2]>d.woodRect[0]&&Math.Abs(d.woodRect[3]-d.woodRect[1])>.00001,"wood UV rectangle");Check(d.means!=null&&d.means.Length==16&&Array.TrueForAll(d.means,v=>!float.IsNaN(v)&&!float.IsInfinity(v)&&v>=0&&v<=1),"far mip means");var seen=new HashSet<string>();foreach(var a in d.assets)Check(a!=null&&a.variant>=0&&a.variant<Ids.Length&&Ids[a.variant]==a.id&&seen.Add(a.id)&&a.assetKey=="tdj/"+a.id&&Array.Exists(all.assets,p=>p.id==a.id&&p.assetKey==a.assetKey),"binding identity");seen.Clear();foreach(var o in d.ornamentsV1??new OrnamentBinding[0]){Check(o!=null&&(o.id==Ids[4]||o.id==Ids[5]||o.id==Ids[6])&&seen.Add(o.id)&&o.assetKey=="tdj/"+o.id&&Array.Exists(d.assets,a=>a.id==o.id),"ornament binding identity");var original=Array.Find(all.chestOrnamentsV1??new ChestPresentationBuilder.Ornament[0],a=>a.id==o.id&&a.assetKey==o.assetKey);Check(original!=null&&original.mesh!=null&&original.mesh.positions!=null&&o.vertices>0&&o.vertices<15000&&o.vertices==original.mesh.positions.Length/3&&o.modes!=null&&o.modes.Length==o.vertices&&Array.TrueForAll(o.modes,v=>v>=0&&v<=3),"ornament mode contract");}ValidateGold(d);}
 static void ValidateGold(Descriptor d){var g=d.goldAtlasV1;if(g==null||string.IsNullOrEmpty(g.id)&&g.version==0)return;Check(g.version==1&&g.id=="gold-parts-atlas-v1"&&g.size==512&&Array.Exists(d.assets,a=>a.id=="treasurechest_gold"),"gold atlas identity");Check(g.colour!=null&&g.colour.colorSpace=="sRGB"&&g.packed!=null&&g.packed.colorSpace=="linear"&&g.packed.channels=="normalX-normalY-roughness-occlusion","gold map contract");foreach(var image in new[]{g.colour,g.packed})Check(!string.IsNullOrEmpty(image.png)&&image.png.Length<2000000,"gold image payload");Check(g.means!=null&&g.means.Length==20&&Array.TrueForAll(g.means,v=>!float.IsNaN(v)&&!float.IsInfinity(v)&&v>=0&&v<=1),"gold face means");}
 static void ValidatePartImage(Image image,bool isColour){Check(image!=null&&image.colorSpace==(isColour?"sRGB":"linear")&&image.channels==(isColour?"RGB-intrinsic-colour":"normalX-normalY-roughness-occlusion"),"part map contract");Check(!string.IsNullOrEmpty(image.png)&&image.png.Length>32&&image.png.Length<2000000,"part PNG length");var b=Convert.FromBase64String(image.png);byte[] signature={137,80,78,71,13,10,26,10};Check(b.Length>=33,"part PNG header");for(int i=0;i<signature.Length;i++)Check(b[i]==signature[i],"part PNG signature");Check(b[8]==0&&b[9]==0&&b[10]==0&&b[11]==13&&b[12]==73&&b[13]==72&&b[14]==68&&b[15]==82,"part IHDR");Check(b[16]==0&&b[17]==0&&b[18]==2&&b[19]==0&&b[20]==0&&b[21]==0&&b[22]==2&&b[23]==0&&b[24]==8&&b[25]==6,"part dimensions/format");}
 static List<PartAtlas> ValidParts(Descriptor d){var result=new List<PartAtlas>();var extension=d.partAtlasesV1;if(extension==null)return result;if(extension.version!=1||extension.size!=512||extension.projection!="chest-five-faces-v1"||extension.origin!="top-left"||extension.atlases==null||extension.atlases.Length==0||extension.atlases.Length>2){Debug.LogWarning("Chest part atlas extension invalid; using legacy surfaces.");return result;}foreach(var a in extension.atlases){try{Check(a!=null&&(a.id=="treasurechest_silver"||a.id=="treasurechest_rainbow")&&a.assetKey=="tdj/"+a.id&&Array.Exists(d.assets,x=>x.id==a.id&&x.assetKey==a.assetKey),"part canonical identity");Check(Array.FindAll(extension.atlases,x=>x!=null&&x.id==a.id).Length==1,"part duplicate identity");Check(a.means!=null&&a.means.Length==20&&Array.TrueForAll(a.means,v=>!float.IsNaN(v)&&!float.IsInfinity(v)&&v>=0&&v<=1),"part face means");ValidatePartImage(a.colour,true);ValidatePartImage(a.packed,false);result.Add(a);}catch(Exception e) when(e is InvalidDataException||e is FormatException){Debug.LogWarning("Chest part atlas ignored: "+e.Message);}}return result;}
 static Texture2D Import(Image image){byte[] bytes=Convert.FromBase64String(image.png);string key=SharedAssetFiles.Hash(bytes)+"/"+image.colorSpace+"/bc7-astc6-v1",path=SharedImportCache.Root+"/chest-"+SharedAssetFiles.Hash(Encoding.UTF8.GetBytes(key))+".png";if(!AssetDatabase.IsValidFolder(SharedImportCache.Root))AssetDatabase.CreateFolder("Assets","MapSharedAssetCache");var saved=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(saved)return saved;Check(!File.Exists(path)&&!File.Exists(path+".meta"),"partial image cache");try{File.WriteAllBytes(path,bytes);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Default;importer.sRGBTexture=image.colorSpace=="sRGB";importer.alphaSource=TextureImporterAlphaSource.FromInput;importer.alphaIsTransparency=false;importer.mipmapEnabled=true;importer.wrapMode=TextureWrapMode.Clamp;importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=2;importer.npotScale=TextureImporterNPOTScale.None;importer.maxTextureSize=512;importer.textureCompression=TextureImporterCompression.CompressedHQ;foreach(string platform in new[]{"Standalone","Android","iPhone"}){var setting=importer.GetPlatformTextureSettings(platform);setting.name=platform;setting.overridden=true;setting.maxTextureSize=512;setting.format=platform=="Standalone"?TextureImporterFormat.BC7:TextureImporterFormat.ASTC_6x6;setting.compressionQuality=75;importer.SetPlatformTextureSettings(setting);}importer.SaveAndReimport();saved=AssetDatabase.LoadAssetAtPath<Texture2D>(path);Check(saved&&saved.width==512&&saved.height==512,"decoded dimensions");return saved;}catch{AssetDatabase.DeleteAsset(path);throw;}}
 static RoyalRelief ValidRoyal(SmallPropsV1.Data all){var d=all.chestSurfacesV1.royalReliefV1;if(d==null)return null;try{Check(d.version==1&&d.id=="gold-royal-relief-v1"&&d.assetKey=="tdj/treasurechest_gold"&&d.size==512&&d.normalEncoding=="tangent-xyz-mikkt"&&d.uvOrigin=="bottom-left","royal contract");var o=Array.Find(all.chestOrnamentsV1??new ChestPresentationBuilder.Ornament[0],x=>x.id=="treasurechest_gold");Check(o!=null&&o.mesh!=null&&o.mesh.positions!=null&&d.vertices==o.mesh.positions.Length/3&&d.vertices>0&&d.vertices<15000,"royal vertices");Check(d.tangents!=null&&d.tangents.Length==d.vertices*4&&d.mask!=null&&d.mask.Length==d.vertices,"royal arrays");for(int i=0;i<d.vertices;i++){float x=d.tangents[i*4],y=d.tangents[i*4+1],z=d.tangents[i*4+2],w=d.tangents[i*4+3];Check(!float.IsNaN(x)&&!float.IsNaN(y)&&!float.IsNaN(z)&&Mathf.Abs(Mathf.Sqrt(x*x+y*y+z*z)-1)<.01f&&Mathf.Abs(w)==1&&(d.mask[i]==0||d.mask[i]==1),"royal TBN/mask");}int index=0;foreach(var im in new[]{d.normal,d.ao}){Check(im!=null&&im.colorSpace=="linear"&&im.channels==(index++==0?"normalXYZ":"occlusionR")&&!string.IsNullOrEmpty(im.png)&&im.png.Length<2000000,"royal image contract");var b=Convert.FromBase64String(im.png);byte[] sig={137,80,78,71,13,10,26,10};Check(b.Length>33,"royal PNG length");for(int k=0;k<sig.Length;k++)Check(b[k]==sig[k],"royal PNG signature");Check(b[16]==0&&b[17]==0&&b[18]==2&&b[19]==0&&b[20]==0&&b[21]==0&&b[22]==2&&b[23]==0&&b[24]==8&&(b[25]==2||b[25]==6),"royal PNG format");}return d;}catch(Exception e)when(e is InvalidDataException||e is FormatException){Debug.LogWarning("Royal relief ignored; legacy mesh remains: "+e.Message);return null;}}
 static RoyalFinish ValidRoyalFinish(RoyalRelief royal){var f=royal.finishV1;if(f==null)return null;try{Check(f.version==1&&f.id=="gold-royal-finish-v1"&&f.size==512&&f.projection=="royal-lid-panels-v1"&&f.uvOrigin=="bottom-left","finish identity");Check(f.vertices==royal.vertices&&f.mask!=null&&f.mask.Length==f.vertices&&Array.TrueForAll(f.mask,x=>x==0||x==1),"finish mask");var im=f.colourRoughness;Check(im!=null&&im.colorSpace=="linear"&&im.channels=="intrinsic-linearRGB-roughnessA"&&!string.IsNullOrEmpty(im.png)&&im.png.Length<2000000,"finish image");var b=Convert.FromBase64String(im.png);byte[] sig={137,80,78,71,13,10,26,10};Check(b.Length>33,"finish PNG length");for(int k=0;k<8;k++)Check(b[k]==sig[k],"finish PNG signature");Check(b[8]==0&&b[9]==0&&b[10]==0&&b[11]==13&&b[12]==73&&b[13]==72&&b[14]==68&&b[15]==82&&b[16]==0&&b[17]==0&&b[18]==2&&b[19]==0&&b[20]==0&&b[21]==0&&b[22]==2&&b[23]==0&&b[24]==8&&b[25]==6,"finish RGBA512");return f;}catch(Exception e)when(e is InvalidDataException||e is FormatException){Debug.LogWarning("Royal finish ignored; base relief remains: "+e.Message);return null;}}
 static WornAtlas ValidWorn(SmallPropsV1.Data all){var d=all.chestSurfacesV1.wornAtlasV1;if(d==null)return null;try{
 Check(d.version==1&&d.id=="worn-board-atlas-v1"&&d.assetKey=="tdj/treasurechest_worn"&&d.size==512&&d.uvOrigin=="top-left","worn identity");
 var a=Array.Find(all.assets,x=>x.id=="treasurechest_worn"&&x.assetKey==d.assetKey);
 Check(a!=null&&Array.Exists(all.chestSurfacesV1.assets,x=>x.id==a.id&&x.assetKey==a.assetKey)&&a.positions!=null&&d.vertices>0&&d.vertices<60000,"worn mesh binding");
 Check(d.uv!=null&&d.uv.Length==d.vertices*2&&Array.TrueForAll(d.uv,x=>!float.IsNaN(x)&&!float.IsInfinity(x)&&x>=0&&x<=1),"worn UV");
 var m=d.mesh;Check(m!=null&&m.positions!=null&&m.normals!=null&&m.colors!=null&&m.positions.Length==d.vertices*3&&m.normals.Length==d.vertices*3&&m.colors.Length==d.vertices*3,"worn visual arrays");Check(Array.TrueForAll(m.positions,x=>!float.IsNaN(x)&&!float.IsInfinity(x)&&Math.Abs(x)<=2)&&Array.TrueForAll(m.normals,x=>!float.IsNaN(x)&&!float.IsInfinity(x))&&Array.TrueForAll(m.colors,x=>!float.IsNaN(x)&&!float.IsInfinity(x)&&x>=0&&x<=1),"worn visual floats");Check(m.triangles!=null&&m.triangles.Length>0&&m.triangles.Length%3==0&&m.triangles.Length<180000&&Array.TrueForAll(m.triangles,x=>x>=0&&x<d.vertices),"worn visual triangles");ValidatePartImage(d.colour,true);
 Check(d.roughness!=null&&d.roughness.colorSpace=="linear"&&d.roughness.channels=="roughnessR","worn roughness contract");
 // Reuse bounded RGBA512 PNG validation; the public roughness channel contract stays distinct.
 ValidatePartImage(new Image{png=d.roughness.png,colorSpace="linear",channels="normalX-normalY-roughness-occlusion"},false);
 return d;}catch(Exception e)when(e is InvalidDataException||e is FormatException){Debug.LogWarning("Worn atlas ignored; legacy UV and wood material remain: "+e.Message);return null;}}
 public string WornKey(string id){return id=="treasurechest_worn"&&worn!=null?"\nworn/"+SharedAssetFiles.Hash(Encoding.UTF8.GetBytes(JsonUtility.ToJson(worn))):"";}
 public Mesh WornVisual(string id,Mesh legacy){if(id!="treasurechest_worn"||worn==null)return legacy;var m=worn.mesh;var mesh=SmallPropsV1.MeshOf(m.positions,m.normals,m.colors,m.triangles);var uv=new List<Vector2>(worn.vertices);for(int i=0;i<worn.vertices;i++)uv.Add(new Vector2(worn.uv[i*2],worn.uv[i*2+1]));mesh.SetUVs(1,uv);mesh.name=id+"-visual";return SharedImportCache.StoreMesh(mesh,"worn-visual/1"+WornKey(id));}
 public void ApplyRoyalLit(GameObject root,string id,string folder){if(HasRoyal(id))new ChestRoyalLitBuilder(royal,folder).Apply(root);}
 public bool HasRoyal(string id){return id=="treasurechest_gold"&&royal!=null;}
 public void ApplyRoyalOrnament(Mesh mesh,string id,float[] uv){if(!HasRoyal(id))return;Check(mesh.vertexCount==royal.vertices&&uv!=null&&uv.Length==royal.vertices*2,"royal mesh binding");var ts=new Vector4[royal.vertices];var coords=new List<Vector2>();var masks=new List<Vector2>();for(int i=0;i<royal.vertices;i++){ts[i]=new Vector4(royal.tangents[i*4],royal.tangents[i*4+1],royal.tangents[i*4+2],royal.tangents[i*4+3]);coords.Add(new Vector2(uv[i*2],uv[i*2+1]));masks.Add(new Vector2(royal.mask[i],finish!=null?finish.mask[i]:0));}mesh.tangents=ts;mesh.SetUVs(0,coords);mesh.SetUVs(4,masks);}
 void ConfigureRoyal(Material m,string id){m.DisableKeyword("CHEST_ROYAL_ROOT");m.DisableKeyword("CHEST_ROYAL_RELIEF");if(m.HasProperty("_RoyalPBR")){m.SetFloat("_RoyalPBR",0);m.SetFloat("_RoyalArtReflection",0);}if(!HasRoyal(id))return;ChestRoyalReflectionBuilder.Configure(m);m.SetFloat("_RoyalRubyEnabled",royal.rubyV1!=null&&royal.rubyV1.version==1&&royal.rubyV1.mode=="opaque-faceted-v1"&&!m.IsKeywordEnabled("CHEST_ORNAMENT")?1:0);m.SetFloat("_RoyalFinishEnabled",finish!=null?1:0);if(finish!=null)m.SetTexture("_RoyalFinish",finishMap);m.EnableKeyword(m.IsKeywordEnabled("CHEST_ORNAMENT")?"CHEST_ROYAL_RELIEF":"CHEST_ROYAL_ROOT");m.SetTexture("_RoyalNormal",royalNormal);m.SetTexture("_RoyalAO",royalAO);m.SetVector("_RoyalColour",new Vector4(.48514994f,.25415209f,.03560131f,1));m.SetVector("_RoyalRuby",new Vector4(.376f,.004f,.018f,1));}
 public ChestSurfaceBuilder(SmallPropsV1.Data all){data=all.chestSurfacesV1;if(data==null||string.IsNullOrEmpty(data.id))return;Validate(all);foreach(var b in data.assets)bindings.Add(b.id,b);foreach(var o in data.ornamentsV1??new OrnamentBinding[0])ornamentBindings.Add(o.id,o);colour=Import(data.colour);packed=Import(data.packed);var w=ValidWorn(all);if(w!=null){try{wornColour=Import(w.colour);wornRoughness=Import(w.roughness);worn=w;}catch(Exception e){Debug.LogWarning("Worn atlas decode failed; legacy fallback: "+e.Message);}}var candidate=ValidRoyal(all);if(candidate!=null){try{royalNormal=Import(candidate.normal);royalAO=Import(candidate.ao);royal=candidate;}catch(Exception e){Debug.LogWarning("Royal relief decode failed; legacy fallback: "+e.Message);}}if(royal!=null){var f=ValidRoyalFinish(royal);if(f!=null){try{finishMap=Import(f.colourRoughness);finish=f;}catch(Exception e){Debug.LogWarning("Royal finish decode failed; base relief remains: "+e.Message);}}}if(data.goldAtlasV1!=null&&data.goldAtlasV1.version==1){goldColour=Import(data.goldAtlasV1.colour);goldPacked=Import(data.goldAtlasV1.packed);}foreach(var a in ValidParts(data)){try{var textures=new[]{Import(a.colour),Import(a.packed)};partAtlases.Add(a.id,a);partTextures.Add(a.id,textures);}catch(Exception e){Debug.LogWarning("Chest part atlas import failed for "+a.id+"; using legacy surface: "+e.Message);}}}
 public bool HasOrnament(string id){return ornamentBindings.ContainsKey(id);}
 public string OrnamentKey(string id){return HasOrnament(id)?"\n"+JsonUtility.ToJson(ornamentBindings[id])+(HasRoyal(id)?"\n"+JsonUtility.ToJson(royal):""):"";}
 public void ApplyOrnament(Mesh mesh,string id){if(!HasOrnament(id))return;var b=ornamentBindings[id];Check(mesh.vertexCount==b.vertices,"ornament vertex order");var uv=new List<Vector2>(b.vertices);foreach(var mode in b.modes)uv.Add(new Vector2(mode,0));mesh.SetUVs(1,uv);}
 public bool Has(string id){return bindings.ContainsKey(id);}
 public string Key(string id){return Has(id)?"-surface-"+id+(id=="treasurechest_worn"&&worn!=null?"-worn-v1-"+SharedAssetFiles.Hash(Encoding.UTF8.GetBytes(JsonUtility.ToJson(worn))):"")+(HasRoyal(id)?"-royal-v7-standard-lit":"")+(HasRoyal(id)&&royal.rubyV1!=null?"-ruby-"+SharedAssetFiles.Hash(Encoding.UTF8.GetBytes(JsonUtility.ToJson(royal.rubyV1))):"")+(HasRoyal(id)&&finish!=null?"-finish-"+SharedAssetFiles.Hash(Encoding.UTF8.GetBytes(JsonUtility.ToJson(finish))):""):"";}
 public Shader ShaderFor(string id,Shader legacy){return Has(id)&&bindings[id].variant<4?Shader.Find("MapSharedProps/ChestWood"):legacy;}
 public void Configure(Material material,string id){if(!Has(id))return;ConfigureRoyal(material,id);if(material.HasProperty("_ChestWornAtlas"))material.SetFloat("_ChestWornAtlas",0);material.DisableKeyword("CHEST_PART_ATLAS");material.DisableKeyword("CHEST_GOLD_ATLAS");material.EnableKeyword("CHEST_SURFACE");material.SetTexture("_ChestColour",colour);material.SetTexture("_ChestPacked",packed);material.SetFloat("_ChestVariant",bindings[id].variant);var means=new Vector4[4];for(int k=0;k<4;k++)means[k]=new Vector4(data.means[k*4],data.means[k*4+1],data.means[k*4+2],data.means[k*4+3]);for(int k=0;k<4;k++)material.SetVector("_ChestMean"+k,means[k]);material.SetVector("_ChestWoodRect",new Vector4(data.woodRect[0],data.woodRect[1],data.woodRect[2],data.woodRect[3]));if(id=="treasurechest_gold"&&goldColour){material.EnableKeyword("CHEST_GOLD_ATLAS");material.SetTexture("_ChestColour",goldColour);material.SetTexture("_ChestPacked",goldPacked);for(int k=0;k<5;k++)material.SetVector("_ChestGoldMean"+k,new Vector4(data.goldAtlasV1.means[k*4],data.goldAtlasV1.means[k*4+1],data.goldAtlasV1.means[k*4+2],data.goldAtlasV1.means[k*4+3]));}if(id=="treasurechest_worn"&&worn!=null){material.SetFloat("_ChestWornAtlas",1);material.SetTexture("_ChestColour",wornColour);material.SetTexture("_ChestPacked",wornRoughness);}if(partAtlases.TryGetValue(id,out var part)){var textures=partTextures[id];material.EnableKeyword("CHEST_PART_ATLAS");material.SetTexture("_ChestColour",textures[0]);material.SetTexture("_ChestPacked",textures[1]);for(int k=0;k<5;k++)material.SetVector("_ChestGoldMean"+k,new Vector4(part.means[k*4],part.means[k*4+1],part.means[k*4+2],part.means[k*4+3]));}}
}
